import { BiomeId, BlockId } from "./blocks";
import { hash2D, portableCos, portableSin } from "./noise";
import { VoxelWorld } from "./voxelWorld";
import type { WorldType } from "./worldTypes";

/**
 * Deterministic terrain generation.
 *
 * ⚠ Saves store only the seed plus block-change deltas, so generateWorld() must
 * produce byte-identical output for a given seed forever. Generation order, the
 * PRNG, the noise functions, and every constant below are part of the save
 * format. generation.test.ts pins the output with SHA-256 digests — if it fails
 * after a change here, the change breaks existing saves.
 */

/**
 * Every value here is part of the save format (see module header). Names exist
 * for readability; changing a value re-rolls every world.
 */
export const GEN = Object.freeze({
  seaLevel: 43,
  borderWallHeight: 14,
  biomes: Object.freeze({
    [BiomeId.Plains]: Object.freeze({ baseHeight: 47, noiseScale: 2.0, treeChance: 0.18 }),
    [BiomeId.Desert]: Object.freeze({ baseHeight: 46, noiseScale: 3.5, treeChance: 0.01 }),
    [BiomeId.Ocean]: Object.freeze({ baseHeight: 30, noiseScale: 2.5, treeChance: 0 }),
    [BiomeId.Forest]: Object.freeze({ baseHeight: 50, noiseScale: 4.0, treeChance: 0.6 }),
    [BiomeId.Mountains]: Object.freeze({ baseHeight: 55, noiseScale: 18.0, treeChance: 0.05 })
  }),
  mountainStoneAboveY: 65,
  snowAboveY: 68,
  // Lava pools in the deepest caves: carved air at or below this Y floods with
  // lava, well under the surface so it stays a deep-cave hazard.
  lavaLevel: 9,
  // Sand shoreline band around sea level (deeper floors keep their biome top).
  beachMaxAboveSea: 1,
  beachDepthBelowSea: 2,
  caveCount: 230,
  caveChamberCount: 150,
  treeAttempts: 9000,
  // Cacti per dry desert column — keyed on area so drowned deserts get few.
  cactusChance: 0.012,
  houseCount: 120,
  dungeonCount: 28,
  // Villages: clusters of houses (reusing placeHouse) on flat, dry land, placed on
  // their own decoupled PRNG (villageRand) so they never shift the shared stream.
  // Each valid site seeds a small resident villager population at boot.
  villageCount: 12,
  villageHouseCount: 5,
  villagersPerVillage: 4,
  villageMinSpawnDistance: 30,
  // A village only lands where the seed-pure surface across its footprint stays
  // within this many blocks (so it sits on flat plains/desert, not a mountainside);
  // a small terrace then levels the rest, keeping the build natural-looking.
  villageFlatnessTolerance: 2,
  oreConfigs: Object.freeze([
    { id: BlockId.SliverOre, attempts: 120000, minY: 3, maxYOffset: 10, minSize: 3, maxSize: 10 },
    { id: BlockId.RubyOre, attempts: 52000, minY: 2, maxYOffset: 16, minSize: 3, maxSize: 10 },
    { id: BlockId.GoldOre, attempts: 36000, minY: 2, maxYOffset: 22, minSize: 3, maxSize: 10 },
    { id: BlockId.SapphireOre, attempts: 28000, minY: 2, maxYOffset: 28, minSize: 2, maxSize: 7 },
    { id: BlockId.DiamondOre, attempts: 18000, minY: 2, maxYOffset: 36, minSize: 2, maxSize: 6 }
  ]),
  // Coal is placed in its own pass on a dedicated PRNG (see placeCoal) so it never
  // shifts the shared `rand` stream — existing ores, trees, and structures stay
  // byte-identical to before coal, exactly as deep-cave lava did. It is the
  // shallowest, most common ore: large veins reaching near the surface.
  coalConfig: Object.freeze({ attempts: 160000, minY: 4, maxYOffset: 8, minSize: 4, maxSize: 12 }),
  // Ocean flora (kelp stalks and reef coral), hash-gated per ocean-floor column
  // like cacti so density follows the actual ocean area. kelpSurfaceClearance is
  // the water that must remain above a stalk's top — kelp is a solid block, so
  // the clearance keeps boats, fishing casts, and the water surface clear of it
  // (random-tick growth enforces the same invariant, see randomTicks.ts).
  oceanFlora: Object.freeze({ kelpChance: 0.03, coralChance: 0.006, kelpMaxHeight: 6, kelpSurfaceClearance: 3 }),
  // Sunken shipwrecks: flooded plank hulls with lazily-filled loot chests on the
  // deep ocean floor, on their own decoupled PRNG (shipwreckRand) like dungeons.
  // Placement attempts, not a guaranteed count: only draws landing in deep ocean
  // build a wreck (~15% of the map), so ~45 attempts yield a handful of wrecks.
  shipwreckCount: 45,
  // Buried treasure: lone chests two blocks under a beach, hunted via the
  // treasure map. Attempts too — the beach band is a thin slice of the map.
  buriedTreasureCount: 90
});

/**
 * The terrain-shaping subset of GEN that a world type can vary: sea level and
 * per-biome surface height (base + noise amplitude). Everything else (caves,
 * ores, lava, trees, structures, dungeons) is type-independent and still reads
 * GEN directly. `terrainConfigFor("default")` returns exactly the GEN values, so
 * the default world stays byte-identical.
 */
export type TerrainConfig = {
  seaLevel: number;
  biomes: Record<BiomeId, { baseHeight: number; noiseScale: number }>;
};

const BIOME_IDS = [BiomeId.Plains, BiomeId.Desert, BiomeId.Ocean, BiomeId.Forest, BiomeId.Mountains] as const;

/** Builds a biome height table from GEN, applying `transform` to each biome's base/scale. */
function biomeHeights(
  transform: (b: { baseHeight: number; noiseScale: number }, id: BiomeId) => { baseHeight: number; noiseScale: number }
): Record<BiomeId, { baseHeight: number; noiseScale: number }> {
  const out = {} as Record<BiomeId, { baseHeight: number; noiseScale: number }>;
  for (const id of BIOME_IDS) {
    const g = GEN.biomes[id];
    out[id] = transform({ baseHeight: g.baseHeight, noiseScale: g.noiseScale }, id);
  }
  return out;
}

// A raised sea with land biomes lifted so they break the surface as gently
// sloped islands (gentle enough that findSpawnOnLand still finds a dry spawn),
// while oceans stay as deep channels between them.
const ISLANDS_BIOMES: Record<BiomeId, { baseHeight: number; noiseScale: number }> = {
  [BiomeId.Plains]: { baseHeight: 54, noiseScale: 4 },
  [BiomeId.Desert]: { baseHeight: 52, noiseScale: 3 },
  [BiomeId.Ocean]: { baseHeight: 34, noiseScale: 3 },
  [BiomeId.Forest]: { baseHeight: 56, noiseScale: 5 },
  [BiomeId.Mountains]: { baseHeight: 64, noiseScale: 16 }
};

