1	import { BlockId } from "./blocks";
2	import { hashU32, portableCos, portableSin } from "./noise";
3	import type { VoxelWorld } from "./voxelWorld";
4	
5	/**
6	 * The nether generator: a solid netherrack mass sealed by bedrock at y=0 AND
7	 * the top row (the ceiling cap is what zeroes baked skylight, giving the
8	 * dimension its dark), hollowed by worm-carved tunnels and broad sea chambers,
9	 * flooded with lava up to `lavaSeaLevel`, hung with glowstone, and seeded with
10	 * deep blazite ore.
11	 *
12	 * Deterministic contracts (mirrors generation.ts):
13	 * - Byte-identical output per (seed, size) forever — pinned by SHA-256
14	 *   baselines in netherGeneration.test.ts. Fix code, never hashes; a
15	 *   deliberate change bumps WORLDGEN_VERSION (one stamp governs BOTH
16	 *   dimensions' diffs — see docs/save-format.md).
17	 * - All noise/trig from lib/world/noise.ts portables (Bun ≡ browser).
18	 * - Own mulberry32 streams xor'd with fresh constants (0x94d049bb caverns,
19	 *   0x3c6ef372 ore) so future passes can't shift each other. The overworld's
20	 *   constants (0x85ebca6b, 0x9e3779b9, 0xc2b2ae35, 0x27d4eb2f) are avoided on
21	 *   principle even though the streams never mix.
22	 * - Attempt counts scale by AREA (unlike GEN's fixed counts) because the
23	 *   engine's headless tests boot tiny nether worlds — fixed counts tuned for
24	 *   512² would hollow a 64² world into one open void.
25	 */
26	export const NETHER_GEN = Object.freeze({
27	  // Carved air at/below this height floods with lava — the seas.
28	  lavaSeaLevel: 32,
29	  // Worm tunnels per 512×512 of area.
30	  wormCount: 120,
31	  // Broad, flat sea chambers per 512×512 — carved low so the lava fills them.
32	  seaChamberCount: 26,
33	  // Glowstone ceiling-cluster gate, applied per eligible ceiling cell.
34	  glowstoneChance: 0.045,
35	  // Blazite veins per 512×512, confined to the deep mass.
36	  blaziteVeinCount: 150,
37	  blaziteMaxY: 40
38	});
39	
40	function mulberry32(seed: number): () => number {
41	  let t = seed >>> 0;
42	  return () => {
43	    t += 0x6d2b79f5;
44	    let r = Math.imul(t ^ (t >>> 15), 1 | t);
45	    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
46	    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
47	  };
48	}
49	
50	/** Attempt count for this world's area, tuned against the 512×512 baseline. */
51	function scaledByArea(count: number, world: VoxelWorld): number {
52	  return Math.max(4, Math.round((count * (world.sizeX * world.sizeZ)) / (512 * 512)));
53	}
54	
55	export function generateNetherWorld(world: VoxelWorld): void {
56	  fillNetherMass(world);
57	  carveNetherCaverns(world, mulberry32((world.seed >>> 0) ^ 0x94d049bb));
58	  floodLavaSea(world);
59	  placeGlowstoneClusters(world);
60	  placeBlaziteOre(world, mulberry32((world.seed >>> 0) ^ 0x3c6ef372));
61	  sealBedrockCaps(world);
62	}
63	
64	/** Solid netherrack between the bedrock caps — the caverns are carved out of it. */
65	function fillNetherMass(world: VoxelWorld): void {
66	  for (let x = 0; x < world.sizeX; x += 1) {
67	    for (let z = 0; z < world.sizeZ; z += 1) {
68	      world.set(x, 0, z, BlockId.Bedrock);
69	      for (let y = 1; y < world.sizeY - 1; y += 1) world.set(x, y, z, BlockId.Netherrack);
70	      world.set(x, world.sizeY - 1, z, BlockId.Bedrock);
71	    }
72	  }
73	}
74	
75	/** Carves a sphere of air, sparing bedrock (shared by worms and chambers). */
76	function carveSphere(world: VoxelWorld, cx: number, cy: number, cz: number, rx: number, ry: number, rz: number): void {
77	  const minX = Math.max(1, Math.floor(cx - rx));
78	  const maxX = Math.min(world.sizeX - 2, Math.ceil(cx + rx));
79	  const minY = Math.max(2, Math.floor(cy - ry));
80	  const maxY = Math.min(world.sizeY - 3, Math.ceil(cy + ry));
81	  const minZ = Math.max(1, Math.floor(cz - rz));
82	  const maxZ = Math.min(world.sizeZ - 2, Math.ceil(cz + rz));
83	  for (let y = minY; y <= maxY; y += 1) {
84	    for (let z = minZ; z <= maxZ; z += 1) {
85	      for (let x = minX; x <= maxX; x += 1) {
86	        const dx = (x - cx) / rx;
87	        const dy = (y - cy) / ry;
88	        const dz = (z - cz) / rz;
89	        if (dx * dx + dy * dy + dz * dz > 1) continue;
90	        if (world.get(x, y, z) !== BlockId.Bedrock) world.set(x, y, z, BlockId.Air);
91	      }
92	    }
93	  }
94	}
95	
96	/**
97	 * Two carving families: winding worm tunnels (the overworld cave walk, thicker
98	 * and with more frequent chamber bursts) and broad flat sea chambers carved low
99	 * so the lava flood turns them into open seas with netherrack shores.
100	 */
101	function carveNetherCaverns(world: VoxelWorld, rand: () => number): void {
102	  const worms = scaledByArea(NETHER_GEN.wormCount, world);
103	  for (let i = 0; i < worms; i += 1) {
104	    let x = 8 + rand() * (world.sizeX - 16);
105	    let y = 8 + rand() * (world.sizeY - 26);
106	    let z = 8 + rand() * (world.sizeZ - 16);
107	    let yaw = rand() * Math.PI * 2;
108	    let pitch = (rand() - 0.5) * 0.3;
109	    const length = 50 + Math.floor(rand() * 70);
110	    for (let step = 0; step < length; step += 1) {
111	      const r = 2.4 + rand() * 3.0;
112	      carveSphere(world, x, y, z, r, r * 0.8, r);
113	      if (rand() > 0.94) {
114	        const burst = 6 + rand() * 6;
115	        carveSphere(world, x, y, z, burst, burst * 0.55, burst);
116	      }
117	      yaw += (rand() - 0.5) * 0.3;
118	      pitch = Math.max(-0.5, Math.min(0.5, pitch + (rand() - 0.5) * 0.18));
119	      x += portableCos(yaw) * 1.2;
120	      z += portableSin(yaw) * 1.2;
121	      y += portableSin(pitch);
122	      if (x < 6 || x > world.sizeX - 6 || z < 6 || z > world.sizeZ - 6 || y < 4 || y > world.sizeY - 12) break;
123	    }
124	  }
125	
126	  const chambers = scaledByArea(NETHER_GEN.seaChamberCount, world);
127	  for (let i = 0; i < chambers; i += 1) {
128	    const cx = 14 + rand() * (world.sizeX - 28);
129	    const cz = 14 + rand() * (world.sizeZ - 28);
130	    const cy = NETHER_GEN.lavaSeaLevel - 6 + rand() * 8; // straddles the flood line
131	    const rx = 12 + rand() * 16;
132	    const rz = 12 + rand() * 16;
133	    const ry = 6 + rand() * 5;
134	    carveSphere(world, cx, cy, cz, rx, ry, rz);
135	  }
136	}
137	
138	/** Carved air at/below the sea level floods with lava — the nether's seas and pools. */
139	function floodLavaSea(world: VoxelWorld): void {
140	  for (let y = 1; y <= NETHER_GEN.lavaSeaLevel; y += 1) {
141	    for (let z = 0; z < world.sizeZ; z += 1) {
142	      for (let x = 0; x < world.sizeX; x += 1) {
143	        if (world.get(x, y, z) === BlockId.Air) world.set(x, y, z, BlockId.Lava);
144	      }
145	    }
146	  }
147	}
148	
149	/** Seeded [0,1) hash of an integer cell position — the per-cell worldgen gate. */
150	function cellHash01(x: number, y: number, z: number, seed: number, salt: number): number {
151	  return (
152	    hashU32((Math.imul(x | 0, 0x9e3779b1) ^ Math.imul(z | 0, 0x85ebca6b) ^ Math.imul(y | 0, 0xc2b2ae35) ^ Math.imul((seed ^ salt) | 0, 0x27d4eb2f)) | 0) /
153	    4294967296
154	  );
155	}
156	
157	/**
158	 * Hangs glowstone off cavern ceilings: an eligible cell has netherrack above
159	 * and open air for at least three cells below (so clusters read as hanging
160	 * lamps, not wall warts). Gated per cell by a seeded position hash — no shared
161	 * PRNG stream, so cluster placement can never shift the carving bytes.
162	 */
163	function placeGlowstoneClusters(world: VoxelWorld): void {
164	  for (let x = 2; x < world.sizeX - 2; x += 1) {
165	    for (let z = 2; z < world.sizeZ - 2; z += 1) {
166	      for (let y = world.sizeY - 4; y > NETHER_GEN.lavaSeaLevel + 4; y -= 1) {
167	        if (world.get(x, y, z) !== BlockId.Air) continue;
168	        if (world.get(x, y + 1, z) !== BlockId.Netherrack) continue;
169	        if (world.get(x, y - 1, z) !== BlockId.Air || world.get(x, y - 2, z) !== BlockId.Air) continue;
170	        if (cellHash01(x, y, z, world.seed, 0x51ed2701) >= NETHER_GEN.glowstoneChance) continue;
171	        // A small hanging blob: the anchor cell, a drip below, a side bud.
172	        world.set(x, y, z, BlockId.Glowstone);
173	        const roll = cellHash01(x, y, z, world.seed, 0x2ab7de19);
174	        if (roll > 0.4) world.set(x, y - 1, z, BlockId.Glowstone);
175	        if (roll > 0.75 && world.get(x + 1, y, z) === BlockId.Air) world.set(x + 1, y, z, BlockId.Glowstone);
176	      }
177	    }
178	  }
179	}
180	
181	/** Blazite veins in the deep mass: small netherrack-replacing blobs, diamond-gated to mine. */
182	function placeBlaziteOre(world: VoxelWorld, rand: () => number): void {
183	  const veins = scaledByArea(NETHER_GEN.blaziteVeinCount, world);
184	  for (let i = 0; i < veins; i += 1) {
185	    const cx = Math.floor(4 + rand() * (world.sizeX - 8));
186	    const cy = Math.floor(2 + rand() * (NETHER_GEN.blaziteMaxY - 2));
187	    const cz = Math.floor(4 + rand() * (world.sizeZ - 8));
188	    const size = 2 + Math.floor(rand() * 4);
189	    let x = cx;
190	    let y = cy;
191	    let z = cz;
192	    for (let n = 0; n < size; n += 1) {
193	      if (world.get(x, y, z) === BlockId.Netherrack) world.set(x, y, z, BlockId.BlaziteOre);
194	      const axis = Math.floor(rand() * 3);
195	      const dir = rand() < 0.5 ? -1 : 1;
196	      if (axis === 0) x = Math.max(1, Math.min(world.sizeX - 2, x + dir));
197	      else if (axis === 1) y = Math.max(2, Math.min(NETHER_GEN.blaziteMaxY, y + dir));
198	      else z = Math.max(1, Math.min(world.sizeZ - 2, z + dir));
199	    }
200	  }
201	}
202	
203	/** Defensive: the caps are load-bearing (skylight zeroing, world border). */
204	function sealBedrockCaps(world: VoxelWorld): void {
205	  for (let x = 0; x < world.sizeX; x += 1) {
206	    for (let z = 0; z < world.sizeZ; z += 1) {
207	      world.set(x, 0, z, BlockId.Bedrock);
208	      world.set(x, world.sizeY - 1, z, BlockId.Bedrock);
209	    }
210	  }
211	}
