10	describe("shipwreck loot tables", () => {
11	  test("every loot entry references an existing item with a sane range", () => {
12	    for (const tier of ALL_TIERS) {
13	      for (const entry of SHIPWRECK_LOOT[tier]) {
14	        expect(ITEM_DEF_BY_ID[entry.itemId]).toBeDefined();
15	        expect(entry.min).toBeLessThanOrEqual(entry.max);
16	        expect(entry.min).toBeGreaterThanOrEqual(0);
17	        if (entry.chance !== undefined) {
18	          expect(entry.chance).toBeGreaterThan(0);
19	          expect(entry.chance).toBeLessThanOrEqual(1);
20	        }
21	      }
22	    }
23	  });
24	
25	  test("rolling the same seed yields identical loot (reproducible until opened)", () => {
26	    const loot1 = rollShipwreckLoot(seededRng(0x1234));
27	    const loot2 = rollShipwreckLoot(seededRng(0x1234));
28	    expect(loot1).toEqual(loot2);
29	  });
30	
31	  test("a low roll opens the rare tier and yields minimum counts", () => {
32	    const loot = rollShipwreckLoot(() => 0);
33	    const byId = new Map(loot.map((d) => [d.itemId, d.count]));
34	    expect(byId.get("diamond_ore")).toBe(1); // rare entry, min 1
35	    expect(byId.get("planks")).toBe(2); // common guaranteed entry, min 2
36	    expect(byId.get("treasure_map")).toBe(1); // the map hunt starts here
