63	 * itemId → single best "how to obtain" hint, precomputed once from the static
64	 * tables. Priority is chosen so each item points at its most natural, repeatable
65	 * source: hunt a common mob (not the one-off boss) → craft → mine → shipwreck →
66	 * fish → dungeon/buried chest → boss. Hunting comes before crafting so a raw drop like wool says "hunt a
67	 * sheep" rather than the obscure craft-from-string path; the boss is last so its
68	 * drops (e.g. diamond ore) prefer mining and only surface the boss for its
69	 * trophy. The first source set for an item wins.
70	 */
71	const SOURCE_HINTS: Map<string, string> = (() => {
72	  const hints = new Map<string, string>();
73	  const set = (itemId: string, hint: string): void => {
74	    if (!hints.has(itemId)) hints.set(itemId, hint);
75	  };
