77	  // 1. Hunt (every mob except the boss — it isn't a farmable source). Entries
78	  // behind a `chance` gate are lucky extras, not the item's natural source
79	  // (the drowned's rare spear shouldn't beat "Craft it"), so they don't hint.
80	  for (const [kind, drops] of Object.entries(MOB_DROPS)) {
81	    if (kind === "boss") continue;
82	    for (const drop of drops) {
83	      if (drop.chance !== undefined) continue;
84	      set(drop.itemId, `Hunt ${MOB_LABELS[kind as MobKind]}`);
85	    }
86	  }
87	  // 2. Craft (incl. smelt/trade/brew). The first recipe producing the item wins.
88	  for (const recipe of RECIPES) set(recipe.result.slotId, CRAFT_VERB[recipe.station ?? "none"]);
