import { expect, test } from "bun:test";
import { PROTOCOL_VERSION, type ServerMessage } from "@/lib/net/protocol";
import type { TicketClaims } from "@/lib/net/tickets";
import * as THREE from "three";
import { createMemoryPersistence } from "./persistence";
import { tickMining } from "@/lib/game/engine/systems/mining";
import { voxelRaycast } from "@/lib/world";
import { lookDirection } from "@/lib/game/engine/systems/playerMotion";
import { Room, type ClientSink } from "./room";

// TEMP repro: does a second joiner's streamed mineHeld actually mine server-side?

function sink(): ClientSink {
  return { send() {}, close() {}, bufferedAmount: () => 0 };
}

function claimsFor(id: string, wid: string, role: "owner" | "member" = "member"): TicketClaims {
  return { sub: id, wid, name: id.toUpperCase(), skinId: null, role, pv: PROTOCOL_VERSION, iat: 0, exp: 9999999999, gm: "creative" } as TicketClaims;
}

const move = { forward: false, back: false, left: false, right: false, jump: false, sprint: false, crouch: false };

test("both joiners' held mining breaks the block under their feet", async () => {
  const persistence = createMemoryPersistence();
  const record = await persistence.loadWorld("w1");
  const room = new Room(record!, persistence, () => 0);
  await room.join(claimsFor("alice", "w1", "owner"), sink());
  await room.join(claimsFor("bob", "w1"), sink());
  const tick = (room as unknown as { tick(dt: number): void }).tick.bind(room);

  for (const id of ["alice", "bob"]) {
    const player = room.engine.state.players.get(id)!;
    const px = player.position.x;
    const py = player.position.y;
    const pz = player.position.z;
    const fx = Math.floor(px);
    const fz = Math.floor(pz);
    const belowY = Math.floor(py) - 1;
    const before = room.engine.state.world.get(fx, belowY, fz);
    console.log(`${id}: gameMode=${player.gameMode} pos=(${px.toFixed(2)},${py.toFixed(2)},${pz.toFixed(2)}) below=(${fx},${belowY},${fz})=${before}`);
    expect(before).not.toBe(0);

    // Aim at the CENTER of the block underfoot (not a fixed straight-down
    // pitch): a fresh joiner sits at exact integer coordinates, i.e. ON the
    // cell boundary, where a fixed slightly-tilted down-aim hugs the boundary
    // into the neighbor column and can miss entirely (a cliff edge).
    const eyeX = px;
    const eyeYw = py + 1.62;
    const eyeZ = pz;
    const tx = fx + 0.5 - eyeX;
    const ty = belowY + 0.5 - eyeYw;
    const tz = fz + 0.5 - eyeZ;
    const len = Math.hypot(tx, ty, tz);
    await room.handleMessage(id, {
      t: "pose",
      d: "overworld",
      seq: id === "alice" ? 1 : 2,
      x: px,
      y: py,
      z: pz,
      yaw: Math.atan2(-tx, -tz),
      pitch: Math.asin(ty / len),
      onGround: true,
      move,
      mineHeld: true
    } as never);

    console.log(
      `${id}: postPose pitch=${player.pitch.toFixed(3)} yaw=${player.yaw.toFixed(3)} mineHeld=${player.input.mineHeld} invOpen=${player.inventoryOpen} dead=${player.isDead} sleeping=${player.sleeping} mounted=${player.mountedVehicleId}`
    );
    for (let i = 0; i < 200; i += 1) tick(0.05); // 10 simulated seconds
    const after = room.engine.state.world.get(fx, belowY, fz);
    console.log(`${id}: after 10s below=${after} mining=${JSON.stringify(player.mining)} pitch=${player.pitch.toFixed(3)} pos=(${player.position.x.toFixed(2)},${player.position.y.toFixed(2)},${player.position.z.toFixed(2)})`);
    // Discriminator: does a DIRECT tickMining call break it?
    tickMining(room.engine.state, player, player.input, 0.05, () => {}, () => 0.5);
    console.log(`${id}: directTickMining below=${room.engine.state.world.get(fx, belowY, fz)} mining=${JSON.stringify(player.mining)}`);
    // Ground truth: the raycast itself.
    const eye = new THREE.Vector3(player.position.x, player.position.y + 1.62, player.position.z);
    const dir = lookDirection(player.yaw, player.pitch, new THREE.Vector3());
    const ray = voxelRaycast(room.engine.state.world, eye, dir, 7);
    console.log(
      `${id}: ray dir=(${dir.x.toExponential(2)},${dir.y.toFixed(4)},${dir.z.toExponential(2)}) -> ${ray ? `hit (${ray.hit.x},${ray.hit.y},${ray.hit.z}) block=${room.engine.state.world.get(ray.hit.x, ray.hit.y, ray.hit.z)} d=${ray.distance.toFixed(2)}` : "NULL"}`
    );
    expect(after).toBe(0);
    // stop mining for the next player
    await room.handleMessage(id, { t: "pose", d: "overworld", seq: id === "alice" ? 10 : 20, x: px, y: py, z: pz, yaw: 0, pitch: 0, onGround: true, move, mineHeld: false } as never);
  }
}, 60000);

