  await forceDigStraightDown(friend);
  await friend.waitForTimeout(1000); // settle (slow CI renderers need the margin — same as the host break)
  await friend.mouse.down();
  // TEMP DIAGNOSTIC: identity check — which player does the replica simulate?
  console.log(
    "FRIEND-ID",
    JSON.stringify(
      await friend.evaluate(() => {
        const m = window.__monecraft!;
        const s = m.engine.state;
        return {
          netId: m.net!.playerId,
          ids: [...s.players.keys()],
          aliasIsNetPlayer: s.player === s.players.get(m.net!.playerId as never)
        };
      })
    )
  );
  // TEMP DIAGNOSTIC: does the replica prediction block even run, and what
  // does the mining ray actually see?
  console.log(
    "FRIEND-RAY",
    JSON.stringify(
      await friend.evaluate(async () => {
        const m = window.__monecraft!;
        const s = m.engine.state;
        const p = s.player;
        const t0 = p.stats.get("play_time") ?? 0;
        await new Promise((resolve) => setTimeout(resolve, 1500));
        const t1 = p.stats.get("play_time") ?? 0;
        const eye = { x: p.position.x, y: p.position.y + 1.62, z: p.position.z };
        const cp = Math.cos(p.pitch);
        const dir = { x: -cp * Math.sin(p.yaw), y: Math.sin(p.pitch), z: -cp * Math.cos(p.yaw) };
        let hit: unknown = null;
        for (let t = 0; t <= 7; t += 0.05) {
          const cx = Math.floor(eye.x + dir.x * t);
          const cy = Math.floor(eye.y + dir.y * t);
          const cz = Math.floor(eye.z + dir.z * t);
          const b = s.world.get(cx, cy, cz);
          if (b !== 0 && b !== 17) {
            hit = { cell: [cx, cy, cz], block: b, dist: +t.toFixed(2) };
            break;
          }
        }
        return { playTimeGrew: t1 > t0, eyeY: +eye.y.toFixed(2), dirY: +dir.y.toFixed(3), hit };
      })
    )
  );
  // TEMP DIAGNOSTIC: sample the friend's input/mining state while digging.
  for (let s = 0; s < 15; s += 1) {
    await friend.waitForTimeout(250);
    const snap = await friend.evaluate(() => {
      const m = window.__monecraft!;
      const s = m.engine.state;
      const p = s.player;
      const fx = Math.floor(p.position.x);
      const fy = Math.floor(p.position.y);
      const fz = Math.floor(p.position.z);
      return {
        ctrlMine: m.input.input.mineHeld,
        engineMine: (p as unknown as { input?: { mineHeld?: boolean } }).input?.mineHeld,
        pitch: +p.pitch.toFixed(2),
        paused: s.paused,
        mode: p.gameMode,
        dead: p.isDead,
        invOpen: p.inventoryOpen,
        chatOpen: (s as unknown as { chatOpen?: boolean }).chatOpen,
        sleep: s.sleepTimer,
        y: +p.position.y.toFixed(2),
        below: [s.world.get(fx, fy - 1, fz), s.world.get(fx, fy - 2, fz)],
        target: p.mining?.targetKey,
        changes: s.blockChanges.changes().length
      };
    });
    console.log("FRIEND-DIG", s, JSON.stringify(snap));
  }
  // The break commits on the FRIEND's own screen despite the lag — its journal
  // grows before a server round trip could have returned the edit.
  await expect
    .poll(() => friend.evaluate(() => window.__monecraft!.engine.state.blockChanges.changes().length), { timeout: 45000 })
    .toBeGreaterThan(friendEdits);
  await friend.mouse.up();
  // …and still crosses the deliberately lagged link to the host.
  await expect
    .poll(() => host.evaluate(() => window.__monecraft!.engine.state.blockChanges.changes().length), { timeout: 45000 })
    .toBeGreaterThan(hostEditsBefore);
  await friend.evaluate(() => window.__monecraft!.net!.setSimulatedLatency(0));

  // ── the owner kicks the friend, who drops to the disconnect modal (LAST: it
  // tears down the friend's session). net.kick is exactly what the RosterPanel
  // Kick button's onClick calls.
  const friendId = await host.evaluate(() => {
    const net = window.__monecraft!.net!;
    return net.roster().find((member) => member.id !== net.playerId)!.id;
  });
  await host.evaluate((id) => window.__monecraft!.net!.kick(id), friendId);
  await expect.poll(() => friend.evaluate(() => window.__monecraft!.net!.status()), { timeout: 30000 }).toBe("closed");
  await expect(friend.getByRole("alertdialog", { name: "Disconnected" })).toBeVisible({ timeout: 10000 });
  await expect.poll(() => host.evaluate(() => window.__monecraft!.engine.state.players.size), { timeout: 30000 }).toBe(1);

  expect(errors, "no console/page errors during the test").toEqual([]);
  await hostContext.close();
  await friendContext.close();
});

